#!/bin/sh
# THE VENDORED BLAKE3, made from its release tarball and nothing else.
# Re-run to upgrade: it replaces vendor/blake3/ and every unit wrapper,
# so what is checked in is always this script's output.
#
#   sh packages/std-hash/vendor/import.sh BLAKE3-1.8.7.tar.gz
#
# ONE OBJECT PER UPSTREAM UNIT. Each wrapper includes one upstream .c
# and nothing else, so every unit compiles as upstream compiles it. The
# SIMD units are the intrinsics forms (no assembly): the Makefile builds
# the ones this machine's architecture carries, under the flags each
# names, and blake3_dispatch picks among them at run time.
set -eu
tar_=$1
sha=c6782a28842b1c0478524ac06a4f2ede784038ee298d6e2162c0b089c4306a3c
here=$(cd "$(dirname "$0")" && pwd)

got=$(shasum -a 256 "$tar_" | cut -d' ' -f1)
if [ "$got" != "$sha" ]; then
    echo "import: $tar_ is not the release this script pins (sha256 $got)" >&2
    exit 1
fi

work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
tar -xzf "$tar_" -C "$work"
src="$work/BLAKE3-1.8.7"

rm -rf "$here/blake3" "$here"/b3_*.c
mkdir -p "$here/blake3"
units="blake3 blake3_dispatch blake3_portable blake3_neon blake3_sse2 blake3_sse41 blake3_avx2 blake3_avx512"
for u in $units; do cp "$src/c/$u.c" "$here/blake3/"; done
cp "$src/c/blake3.h" "$src/c/blake3_impl.h" "$here/blake3/"
cp "$src/LICENSE_A2" "$src/LICENSE_A2LLVM" "$src/LICENSE_CC0" "$here/blake3/"
cp "$src/test_vectors/test_vectors.json" "$here/blake3/"
for u in $units; do
    printf '/* generated by import.sh: one upstream unit */\n#include "blake3/%s.c"\n' "$u" > "$here/b3_$u.c"
done
